package com.netflix.frigga.ami;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class AppVersionTest {

    @Test
    public void parseName_EmptyStringReturnsNull() {
        assertEquals(null, AppVersion.parseName(""));
    }

    @Test
    public void parseName_SimpleVersionReturnsInstance() {
        String amiName = "ami-123";
        AppVersion appVersion = AppVersion.parseName(amiName);
        assertNotNull(appVersion);
    }

    @Test
    public void parseName_InvalidVersionThrowsException() {
        String amiName = "invalid-ami-name";
        assertThrows(Exception.class, () -> AppVersion.parseName(amiName));
    }

    @Test
    public void compareTo_MatchesVersionsReturnsZero() {
        AppVersion appVersion1 = new AppVersion("ami-123");
        AppVersion appVersion2 = new AppVersion("ami-456");
        assertEquals(0, appVersion1.compareTo(appVersion2));
    }

    @Test
    public void compareTo_DifferentBuildJobsReturnsCorrectOrder() {
        AppVersion appVersion1 = new AppVersion("ami-123");
        AppVersion appVersion2 = new AppVersion("ami-456");
        assertTrue(appVersion1.compareTo(appVersion2) < 0);
    }

    @Test
    public void getAppVersionPattern_ReturnsCorrectPattern() {
        Pattern pattern = AppVersion.getAppVersionPattern();
        assertNotNull(pattern);
        assertTrue(pattern.matcher("ami-123").find());
    }

    @Test
    public void getPackageName_ReturnsCorrectPackage() {
        AppVersion appVersion = new AppVersion("ami-123");
        assertEquals(NameConstants.APP_VERSION_PACKAGE, appVersion.getPackageName());
    }

    @Test
    public void getVersion_ReturnsCorrectVersion() {
        AppVersion appVersion = new AppVersion("ami-123");
        assertEquals("123", appVersion.getVersion());
    }

    @Test
    public void getBuildJobName_ReturnsCorrectBuildJobName() {
        AppVersion appVersion = new AppVersion("ami-123");
        assertEquals("build-job-name", appVersion.getBuildJobName());
    }

    @Test
    public void getBuildNumber_ReturnsCorrectBuildNumber() {
        AppVersion appVersion = new AppVersion("ami-123");
        assertEquals("build-number", appVersion.getBuildNumber());
    }

    @Test
    public void getCommit_ReturnsCorrectCommit() {
        AppVersion appVersion = new AppVersion("ami-123");
        assertEquals("commit-hash", appVersion.getCommit());
    }

    @Test
    public void getChangelist_ReturnsDeprecatedValue() {
        AppVersion appVersion = new AppVersion("ami-123");
        assertNotNull(appVersion.getChangelist()); // deprecated method, but should return value
    }

    @Test
    public void toString_ReturnsCorrectStringRepresentation() {
        AppVersion appVersion = new AppVersion("ami-123");
        String expected = "ami-123 (build-job-name: build-number, commit-hash)";
        assertEquals(expected, appVersion.toString());
    }

    @Test
    public void hashCode_ReturnsCorrectHashCode() {
        AppVersion appVersion1 = new AppVersion("ami-123");
        AppVersion appVersion2 = new AppVersion("ami-456");
        assertNotEquals(appVersion1.hashCode(), appVersion2.hashCode());
    }

    @Test
    public void equals_MatchesVersionsReturnsTrue() {
        AppVersion appVersion1 = new AppVersion("ami-123");
        AppVersion appVersion2 = new AppVersion("ami-123");
        assertTrue(appVersion1.equals(appVersion2));
    }

    @Test
    public void equals_DifferentBuildJobsDoesNotReturnTrue() {
        AppVersion appVersion1 = new AppVersion("ami-123");
        AppVersion appVersion2 = new AppVersion("ami-456");
        assertFalse(appVersion1.equals(appVersion2));
    }
}
